<section class="card"><div class="stay-actions"><div><h2>Weekly Area Audit</h2><p>Shared, service and outdoor areas, with tracked follow-ups.</p></div><?php $link('Audit An Area',['section'=>'areas','form'=>'area_audit'],'');?></div>

<form method="get" action="<?=access_h(stay_url())?>#area-register" class="stay-form"><input type="hidden" name="section" value="areas"><?php stay_input('Week Containing','week',$areaAudits['week'] ?? gmdate('Y-m-d'),'date',true);?><div class="stay-actions"><button class="button" type="submit">Apply Filter</button><a class="button secondary" href="<?=$url(['section'=>'areas'])?>#area-register">Current Week</a><a class="button secondary" href="<?=$url(['section'=>'areas','range'=>'all'])?>#area-register">All Weeks</a></div></form>
<p class="stay-help"><?=$areaAudits['week']?'Week Of '.access_h(display_date($areaAudits['week'])).' · Monday–Sunday (UTC)':'All Weeks'?></p></section>
<div id="area-register" tabindex="-1"></div>
<?php foreach($areaAudits['rows'] as $row):$audit=$row['data'];$managed=(new \Tivoli\Service\WeeklyAuditService(access_service()))->association('area',$row['target_id']);$managedCase=$managed?(new \Tivoli\Service\WeeklyAuditService(access_service()))->detail($actor,$managed):null;?>
<section class="card"><div class="stay-actions"><h2><?=access_h($audit['area'])?></h2><span class="stay-badge"><?=access_h($managedCase?match($managedCase['status']){'unassigned'=>'Needs Assignment','assigned'=>'In Progress','review'=>'Awaiting Verification','closed'=>'Verified & Closed'}:stay_label(str_replace('_',' ',$audit['status'])))?></span></div>
<?php if($audit['status']!=='completed'&&$audit['due_date']!==''&&$audit['due_date']<gmdate('Y-m-d')):?><p class="error">Follow-Up Overdue</p><?php endif?><p>Week Of <?=access_h(display_date($audit['week']))?> · <?=$audit['result']==='corrective'?'Needs Attention':access_h(stay_label($audit['result']))?></p>
<p class="stay-help">Audited <?=access_h(display_date($audit['audit_date']))?> · Recorded By <?=access_h($row['actor_name'] ?? 'Unknown Historical Actor')?> · <?=access_h(display_date($row['occurred_at']))?> UTC</p>
<details><summary><?=empty($audit['checks'])?'View Audit Details':'View Checks & Comments'?></summary><?php foreach($audit['checks'] as $check):?><p><strong><?=access_h($check['label'])?>:</strong> <?=$check['result']==='corrective'?'Needs Attention':access_h(stay_label(str_replace('_',' ',$check['result'])))?></p><?php endforeach?>
<p>Comment: <?=access_h($audit['comment'] ?: 'Not Recorded')?></p><p>Owner: <?=access_h($audit['owner'] ?: 'Not Assigned')?> · Due: <?=access_h(display_date($audit['due_date'] ?: 'Not Set'))?></p>
<?php if($row['followup']):?><p>Latest Follow-Up: <?=access_h($row['followup']['comment'] ?: 'No Comment')?> · <?=access_h($row['followup']['actor_name'] ?? 'Unknown Historical Actor')?> · <?=access_h(display_date($row['followup']['occurred_at']))?> UTC</p><?php endif?></details>
<div class="stay-actions"><?php if(!$managedCase||$managedCase['status']!=='closed')$link('Update Follow-Up',['section'=>'areas','range'=>'all','form'=>'area_followup','audit_key'=>$row['target_id']]);?><a class="button secondary" href="<?=$url(['section'=>'areas','range'=>'all','history'=>$row['target_id']])?>#area-history">View History</a></div></section>
<?php endforeach;if(!$areaAudits['rows']):?><section class="card"><p>No area audits recorded for this period.</p></section><?php endif?>
<?php if($areaAudits['next_before']):$range=$areaAudits['week']?['week'=>$areaAudits['week']]:['range'=>'all'];?><a class="button secondary" href="<?=$url(['section'=>'areas','before'=>$areaAudits['next_before']]+$range)?>#area-register">Older Audits</a><?php endif?>
<?php if(!empty($areaAudits['history'])):?><section class="card" id="area-history" tabindex="-1"><h2>Audit History</h2>
<?php foreach($areaAudits['history'] as $event):?><article class="stay-event"><strong><?=access_h(stay_event_label($event['action']))?> · <?=access_h(stay_label(str_replace('_',' ',$event['data']['status'])))?></strong><p><?=access_h($event['data']['comment'] ?: 'No Comment')?></p><p>Owner: <?=access_h($event['data']['owner'] ?: 'Not Assigned')?> · Due: <?=access_h(display_date($event['data']['due_date'] ?: 'Not Set'))?></p><?php if(!empty($event['data']['checks'])):?><details><summary>Original Checks</summary><?php foreach($event['data']['checks'] as $check):?><p><?=access_h($check['label'])?>: <?=access_h(stay_label(str_replace('_',' ',$check['result'])))?></p><?php endforeach?></details><?php endif?><small><?=access_h($event['actor_name'] ?? 'Unknown Historical Actor')?> · <?=access_h(display_date($event['occurred_at']))?> UTC</small></article><?php endforeach?>
<?php if($areaAudits['history_next']):?><a class="button secondary" href="<?=$url(['section'=>'areas','range'=>'all','history'=>$_GET['history'],'history_before'=>$areaAudits['history_next']])?>#area-history">Older History</a><?php endif?></section><?php endif?>
